# -*- coding: utf-8 -*-
"""France / Sciences et technologie : CM1, CM2（cycle 3）"""
from fr_sci import H, nq, num


def f_meteo(R):
    k = R.choice(["ecart", "ecart", "moy", "pluie", "baisse"])
    if k == "ecart":
        lo, hi = R.choice([(4, 13), (-3, 6), (12, 25), (8, 19), (-5, 2), (15, 31), (6, 17), (2, 11)])
        return nq("Ce matin, le thermomètre indiquait %s °C. L’après-midi, il indiquait %s °C. De combien de degrés la température a-t-elle augmenté ?" % (num(lo), num(hi)), hi - lo,
                  [hi + lo if hi + lo != hi - lo else hi, abs(lo) + 1, hi], "°C", "%s − (%s) = %s °C." % (num(hi), num(lo), num(hi - lo)))
    if k == "moy":
        a = R.choice([[10, 12, 14], [6, 9, 12], [15, 18, 21], [20, 22, 27], [3, 5, 10], [11, 14, 20], [8, 8, 11]])
        m = sum(a) / 3
        return nq("Les températures de trois jours sont %s °C, %s °C et %s °C. Quelle est la température moyenne ?" % tuple(num(x) for x in a), m,
                  [sum(a), max(a) - min(a), max(a)], "°C", "(%s + %s + %s) : 3 = %s : 3 = %s °C." % (num(a[0]), num(a[1]), num(a[2]), num(sum(a)), num(m)))
    if k == "pluie":
        a = R.choice([[5, 12, 0, 8], [3, 3, 10, 4], [15, 0, 2, 7], [6, 9, 1, 0], [20, 4, 6, 10], [2, 2, 3, 13]])
        return nq("Le pluviomètre a mesuré %s mm, %s mm, %s mm et %s mm de pluie en quatre jours. Combien de pluie est tombée en tout ?" % tuple(num(x) for x in a), sum(a),
                  [sum(a) / 4, max(a), sum(a) + 10], "mm", "%s = %s mm." % (" + ".join(num(x) for x in a), num(sum(a))))
    hi, lo = R.choice([(14, 6), (9, -2), (22, 15), (5, -4), (18, 7), (12, 3)])
    return nq("Le soir, il faisait %s °C. La nuit, la température est descendue à %s °C. De combien de degrés a-t-elle baissé ?" % (num(hi), num(lo)), hi - lo,
              [hi + lo if hi + lo != hi - lo else hi + 1, hi, abs(lo) + 2], "°C", "%s − (%s) = %s °C." % (num(hi), num(lo), num(hi - lo)))


def f_masse(R):
    k = R.choice(["sel", "sel", "conv", "conv2", "depl"])
    if k == "sel":
        e, s = R.choice([(200, 10), (150, 20), (300, 15), (250, 30), (500, 25), (400, 12), (100, 8)])
        return nq("On dissout %d g de sel dans %d g d’eau. Quelle est la masse de l’eau salée ?" % (s, e), e + s, [e, e - s, s], "g",
                  "Le sel ne disparaît pas : %d + %d = %d g. La masse se conserve." % (e, s, e + s))
    if k == "conv":
        g = R.choice([1500, 2500, 3200, 750, 4250, 1200])
        return nq("Un sac de pommes pèse %s g. Combien de kilogrammes pèse-t-il ?" % num(g), g / 1000, [g / 100, g / 10, g * 1000], "kg", "%s g = %s kg car 1 kg = 1 000 g." % (num(g), num(g / 1000)))
    if k == "conv2":
        kg = R.choice([1.5, 2.5, 0.5, 3.2, 0.25, 4.5])
        return nq("Combien de grammes font %s kg ?" % num(kg), kg * 1000, [kg * 100, kg * 10, kg + 1000], "g", "%s kg × 1 000 = %s g." % (num(kg), num(kg * 1000)))
    v0, v1 = R.choice([(50, 62), (100, 125), (200, 230), (60, 75), (80, 96), (150, 168)])
    return nq("Dans une éprouvette, l’eau arrive à %d mL. On plonge un caillou : l’eau monte à %d mL. Quel est le volume du caillou ?" % (v0, v1), v1 - v0, [v1, v0, v1 + v0], "mL",
              "Volume du caillou = %d − %d = %d mL (ou %d cm³)." % (v1, v0, v1 - v0, v1 - v0))


